function test_stage4a6_1_optimizer_stability()
%TEST_STAGE4A6_1_OPTIMIZER_STABILITY Known noiseless fits are finite/repeatable.
    root=fileparts(fileparts(mfilename('fullpath')));addpath(fullfile(root,'src'),fullfile(root,'config'));cfg=default_config(root);sc=stage4a6_1_optimizer_config(cfg,'smoke');g=generate_radial_topology_candidates(sc.generator);d=build_extended_parameter_domain(sc.parameter_search,0.5);f=sc.grids(1).frequency_hz(1:9);theta=struct('main_length_scale',1,'branch_length_scale',1,'branch_load_scale',1,'source_impedance_ohm',50,'receiver_impedance_ohm',50,'regularization',NaN);[n,lc]=topology_apply_parameters(g(1).network,cfg,theta);[m,~]=plc_measurement_bundle('siso_forward',n,theta,lc);[obs,~]=plc_multiview_response(f,n,m,lc);mask=topology_active_parameter_mask(g(1),d.names);b=struct('names',{d.names(mask)},'lower',d.in_lower(mask),'upper',d.in_upper(mask));o=sc.optimization;o.multi_start_count=2;o.max_iterations=120;o.max_function_evaluations=400;o.profile=struct('enabled',false);r1=optimize_stage4a6_1_parameters(obs,f,g(1),cfg,b,theta,o);r2=optimize_stage4a6_1_parameters(obs,f,g(1),cfg,b,theta,o);assert(r1.residual_finite&&r1.optimizer_converged,'Known fit did not converge with finite residual.');assert(abs(r1.distance-r2.distance)<1e-12&&norm(r1.theta_vector-r2.theta_vector)<1e-10,'Known fit is not deterministic.');fprintf('ALL STAGE 4A.6.1 OPTIMIZER STABILITY TESTS PASSED\n');
end
